'use strict';
const countries = window.ENERGY_DATA;
const byName = name => countries.find(d => d.country === name);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = value => value === '' || value === null || value === undefined ? null : Number.isFinite(Number(value)) ? Number(value) : null;
const fmt = (value, digits = 1) => num(value) === null ? 'Unavailable' : Number(value).toLocaleString('en-US', {maximumFractionDigits:digits});
const compact = value => num(value) === null ? 'Unavailable' : new Intl.NumberFormat('en-US', {notation:'compact', maximumFractionDigits:2}).format(Number(value));
const money = value => num(value) === null ? 'Unavailable' : '$' + fmt(Number(value) / 1000, 2) + 'B';
const source = (url, label='Source ↗') => url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>` : 'No verified source in this release';
const available = key => countries.filter(d => num(d[key]) !== null).length;
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const monthly = d => months.map((_, i) => num(d['accommodation_nights_month_' + String(i + 1).padStart(2,'0')]));
const seasonStats = d => {const values = monthly(d);if(values.some(v=>v===null))return null;const total=values.reduce((a,b)=>a+b,0);if(total<=0)return null;const sorted=values.map((v,i)=>({v,i})).sort((a,b)=>b.v-a.v);return {values,total,peak:sorted[0].i,top2:(sorted[0].v+sorted[1].v)/total*100,topMonths:sorted.slice(0,2).map(x=>months[x.i]).join(' & ')};};
const state = {tab:document.body.dataset?.page||'overview',focus:'Croatia',reference:'France',metric:'travel_receipts_usd_million',arrivalType:'Tourists',compare:['Croatia','France','Germany','Japan'],query:'',sort:'country',dir:1,coverage:'all',placeQuery:''};
const metricNames={travel_receipts_usd_million:'Travel receipts',tourism_arrivals:'Inbound arrivals',inbound_accommodation_nights:'Inbound accommodation nights',air_passengers_carried:'Airline passengers',accommodation_bed_places:'Accommodation bed places'};
const units={travel_receipts_usd_million:'USD billions · 2024',tourism_arrivals:'Trips · 2024',inbound_accommodation_nights:'Nights · 2024',air_passengers_carried:'Passengers · 2023',accommodation_bed_places:'Bed places · 2024'};
const displayMetric=(d,key)=>key==='travel_receipts_usd_million'?money(d[key]):compact(d[key]);
const card=(label,value,note,accent=false)=>`<article class="card ${accent?'accent':''}"><div class="label">${esc(label)}</div><div class="big">${esc(value)}</div><small>${esc(note)}</small></article>`;
const buttonCountry=d=>`<button class="link" data-profile="${esc(d.country)}">${esc(d.country)}</button>`;
const empty=message=>`<div class="empty">${esc(message)}</div>`;
function coverageRows(){return [['Visitor counts','tourism_arrivals'],['Travel receipts','travel_receipts_usd_million'],['Inbound accommodation nights','inbound_accommodation_nights'],['Monthly demand','seasonality_year'],['Accommodation capacity','accommodation_bed_places'],['Airline activity','air_passengers_carried'],['Resident survey','resident_growth_support_pct']].map(([label,key])=>`<div class="coverage"><span>${label}</span><span class="tag ${available(key)<16?'gap':''}">${available(key)} / 16</span></div>`).join('');}
function chart(){
 const key=state.metric;
 let rows=countries.filter(d=>num(d[key])!==null);
 if(key==='tourism_arrivals')rows=rows.filter(d=>d.tourism_arrivals_type===state.arrivalType);
 rows.sort((a,b)=>Number(b[key])-Number(a[key]));const max=Math.max(...rows.map(d=>Number(d[key])),1);
 const notes={travel_receipts_usd_million:'Travel exports excluding international passenger transport. Current USD; currency movements affect comparisons.',tourism_arrivals:'Only the selected arrival definition is shown. Country methods still differ; see each country brief. Counts are trips, not unique people.',inbound_accommodation_nights:'Visitor and accommodation-provider surveys differ in coverage. These totals are not occupancy rates.',air_passengers_carried:'Nationally registered airlines, domestic and international routes. This is aviation activity, not tourist arrivals or destination access.',accommodation_bed_places:'Reported hotels, holiday/short-stay accommodation and camping. National reporting thresholds apply.'};
 return `<div class="panel-head"><div><h2>${esc(metricNames[key])}</h2><p class="sub">${units[key]} · ${rows.length} countries with data</p></div><select id="metric" aria-label="Chart metric">${Object.entries(metricNames).map(([k,v])=>`<option value="${k}" ${k===key?'selected':''}>${v}</option>`).join('')}</select></div>${key==='tourism_arrivals'?`<label class="field">ARRIVAL DEFINITION <select id="arrival-type">${['Tourists','Visitors','Accommodation arrivals'].map(t=>`<option ${t===state.arrivalType?'selected':''}>${t}</option>`).join('')}</select></label>`:''}<div class="legend"><span><i class="dot"></i>Focus country</span><span><i class="dot ref"></i>Reference</span></div><div role="group" aria-label="${esc(metricNames[key])} by country">${rows.map(d=>`<div class="bar-row ${d.country===state.focus?'selected':d.country===state.reference?'reference':''}"><button data-profile="${esc(d.country)}">${esc(d.country)}</button><div class="bar-track"><div class="bar-fill" style="width:${Number(d[key])/max*100}%"></div></div><span class="bar-value">${esc(displayMetric(d,key))}</span></div>`).join('')}</div><p class="sub">${notes[key]}</p><small class="sub">Ordering applies only to the selected dataset and definition. Missing observations are excluded.</small>`;
}
function overview(){
 const d=byName(state.focus),r=byName(state.reference),s=seasonStats(d),a=num(d.travel_receipts_usd_million),b=num(r.travel_receipts_usd_million);
 const delta=a!==null&&b!==null&&b!==0?(a-b)/b*100:null;
 return `<div class="grid">${card(d.country+' · inbound arrivals',compact(d.tourism_arrivals),(d.tourism_arrivals_year||'No verified year')+' · '+(d.tourism_arrivals_type||'Not verified'))}${card('Travel receipts · 2024',money(d.travel_receipts_usd_million),delta===null?'Reference comparison unavailable':`${Math.abs(delta).toFixed(1)}% ${delta>=0?'higher':'lower'} than ${r.country}`,true)}${card('Two busiest months',s?fmt(s.top2)+'%':'Unavailable',s?`${s.topMonths} · share of annual nights · 2024`:'Monthly accommodation data not verified')}${card('Resident growth support',num(d.resident_growth_support_pct)!==null?d.resident_growth_support_pct+'%':'Unavailable',d.resident_survey_year?d.resident_survey_year+' · national survey':'No national survey verified')}</div>
 <div class="split"><section class="panel" id="chart-panel">${chart()}</section><aside><section class="panel"><p class="eyebrow">COUNTRY READING</p><h2>${esc(d.country)} in context</h2><div class="insight"><span class="number">01 / DEMAND</span><p>${num(d.tourism_arrivals)!==null?`${compact(d.tourism_arrivals)} recorded arrivals in 2024. ${esc(d.tourism_arrivals_basis)}.`:'A 2024 visitor count is unavailable in this release. This is an evidence gap, not evidence of low demand.'}</p></div><div class="insight"><span class="number">02 / TIMING</span><p>${s?`${fmt(s.top2)}% of reported annual accommodation nights fall in ${s.topMonths}. Check local capacity before deciding whether to shift promotion to quieter months.`:'Monthly demand is not verified. Annual totals cannot identify the best months for a campaign.'}</p></div><div class="insight"><span class="number">03 / LOCAL VOICES</span><p>${d.resident_survey_year?`${d.resident_growth_support_pct}% support continued promotion in the national survey. Check local results before applying this to a destination.`:'Resident feedback is missing. Visitor growth alone cannot show whether communities benefit.'}</p></div><button class="secondary" data-profile="${esc(d.country)}">Review evidence & sources ↗</button></section><section class="panel section-gap"><h3>What this release covers</h3>${coverageRows()}</section></aside></div><div class="note warn">${esc(d.tourism_notes)}</div>`;
}
const compareMetrics=[
 ['Inbound arrivals',d=>compact(d.tourism_arrivals),d=>(d.tourism_arrivals_year||'')+' · '+(d.tourism_arrivals_basis||'Not verified')],
 ['Travel receipts',d=>money(d.travel_receipts_usd_million),d=>d.travel_receipts_year?'2024 · excludes international passenger transport':'Not verified'],
 ['Inbound accommodation nights',d=>compact(d.inbound_accommodation_nights),d=>d.accommodation_nights_year?'2024 · '+d.accommodation_nights_basis:'Not verified'],
 ['Bed places',d=>compact(d.accommodation_bed_places),d=>d.accommodation_capacity_year?'2024 · hotels, short stays and camping':'Not verified'],
 ['Two busiest months',d=>{const s=seasonStats(d);return s?fmt(s.top2)+'%':'Unavailable';},d=>{const s=seasonStats(d);return s?s.topMonths+' · 2024 · all guest nights':'Monthly demand not verified';}],
 ['Attraction example',d=>d.attraction_example,()=> 'Illustrative heritage place; not a popularity ranking'],
 ['Airline passengers',d=>compact(d.air_passengers_carried),()=> '2023 · national carriers, all route types; not inbound tourists'],
 ['Resident growth support',d=>num(d.resident_growth_support_pct)!==null?d.resident_growth_support_pct+'%':'Unavailable',d=>d.resident_survey_year?'2024 · national survey; see wording and limitations':'National survey not verified'],
 ['Business electricity',d=>num(d.business_price_usd_per_kwh)!==null?'$'+fmt(d.business_price_usd_per_kwh,3)+'/kWh':'Unavailable',d=>d.price_period+' · recorded business rate, not hotel-specific']
];
function compareTable(){const selected=state.compare.map(byName);return !selected.length?empty('Choose up to four countries above to compare.'): `<div class="table-wrap"><table class="comparison"><thead><tr><th scope="col">Measure</th>${selected.map(d=>`<th scope="col">${buttonCountry(d)}</th>`).join('')}</tr></thead><tbody>${compareMetrics.map(([label,get,note])=>`<tr><td>${label}</td>${selected.map(d=>`<td><span class="metric-value">${esc(get(d))}</span><small>${esc(note(d))}</small></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function compare(){return `<section class="panel"><div class="panel-head"><div><h2>Compare countries</h2><p class="sub">Choose up to four. Keep the definition and reporting year beside the number.</p></div><span class="tag" id="compare-count">${state.compare.length} / 4 selected</span></div><input type="search" id="country-search" aria-label="Search countries to compare" placeholder="Find a country…"><div class="picker" id="picker">${countries.slice().sort((a,b)=>a.country.localeCompare(b.country)).map(d=>`<label data-country-label="${esc(d.country.toLowerCase())}"><input type="checkbox" name="compare" value="${esc(d.country)}" ${state.compare.includes(d.country)?'checked':''} ${state.compare.length===4&&!state.compare.includes(d.country)?'disabled':''}>${esc(d.country)}</label>`).join('')}</div><div class="note">Country totals differ in scale and method. This comparison does not score destination quality, local capacity or community wellbeing.</div><div id="comparison-table">${compareTable()}</div></section>`;}
function seasonChart(d){const s=seasonStats(d);if(!s)return empty(`Monthly accommodation nights are unavailable for ${d.country}. No seasonal pattern has been estimated.`);const max=Math.max(...s.values);return `<div class="season-chart" role="img" aria-label="Monthly share of annual accommodation nights in ${esc(d.country)} in 2024">${s.values.map((v,i)=>`<div class="month ${i===s.peak?'peak':''}" title="${months[i]}: ${fmt(v,0)} nights (${fmt(v/s.total*100)}%)"><span class="pct">${fmt(v/s.total*100)}%</span><div class="col" style="height:${v/max*170}px"></div><small>${months[i]}</small></div>`).join('')}</div><div class="note"><strong>${fmt(s.top2)}%</strong> of annual nights occur in ${s.topMonths}. Total: ${compact(s.total)} nights.</div><details><summary>Exact monthly values</summary><div class="table-wrap"><table><thead><tr><th>Month</th><th>Nights</th><th>Annual share</th></tr></thead><tbody>${s.values.map((v,i)=>`<tr><td>${months[i]}</td><td>${fmt(v,0)}</td><td>${fmt(v/s.total*100,2)}%</td></tr>`).join('')}</tbody></table></div></details><p class="sub">${source(d.seasonality_source_url,'Eurostat monthly accommodation nights ↗')}</p>`;}
function season(){const d=byName(state.focus),r=byName(state.reference);return `<div class="note">Monthly series are verified for Croatia, France and Germany. All charts use 2024 nights for domestic and international guests in hotels, short stays and camping. Missing countries remain selectable.</div><div class="toolbar"><span class="sub">Explore available data:</span>${countries.filter(d=>d.seasonality_year).map(d=>`<button class="secondary" data-focus="${esc(d.country)}">${esc(d.country)}</button>`).join('')}</div><div class="split"><section class="panel"><h2>${esc(d.country)}</h2><p class="sub">Share of annual accommodation nights · 2024</p>${seasonChart(d)}</section><section class="panel"><h2>${esc(r.country)}</h2><p class="sub">Reference · same metric and year</p>${seasonChart(r)}</section></div><div class="grid">${card('Focus · bed places',compact(d.accommodation_bed_places),d.accommodation_capacity_year||'No capacity verified')}${card('Reference · bed places',compact(r.accommodation_bed_places),r.accommodation_capacity_year||'No capacity verified')}${card('Focus · inbound nights',compact(d.inbound_accommodation_nights),d.accommodation_nights_year||'No inbound nights verified')}${card('Reference · inbound nights',compact(r.inbound_accommodation_nights),r.accommodation_nights_year||'No inbound nights verified')}</div><div class="note warn">Capacity and annual nights do not establish occupancy or remaining capacity. Bed availability, opening days, local concentration and survey coverage must match before calculating a rate.</div><section class="panel"><h3>Use the pattern to ask better planning questions</h3><ul class="fact-list"><li>Can attractions, accommodation and transport support a campaign in quieter months?</li><li>Where do national peaks coincide with local crowding, water demand or housing pressure?</li><li>Do residents support promotion, and does that support change across seasons?</li></ul></section>`;}
function placeCards(){return countries.filter(d=>d.country.toLowerCase().includes(state.placeQuery.toLowerCase())).map(d=>`<article class="card"><h3>${buttonCountry(d)}</h3><span class="tag">Attraction example</span><div class="place-name">${esc(d.attraction_example)}</div><p>${source(d.attraction_source_url,'UNESCO heritage listing ↗')}<br>Illustrative place, not a popularity ranking.</p><div class="coverage"><span>Airline passengers · 2023</span><strong>${compact(d.air_passengers_carried)}</strong></div><p>National carriers on domestic and international routes. Not visitors to the country.</p>${source(d.air_transport_source_url,'World Bank / ICAO ↗')}</article>`).join('')||empty('No countries match your search.');}
function place(){return `<section class="panel"><div class="panel-head"><div><h2>The visitor offer and transport context</h2><p class="sub">A starting point for national comparison. Attraction examples do not show visitor volume or current opening status.</p></div><span class="tag">16 countries</span></div><div class="note warn">Airline activity is not connectivity. Route schedules, inbound seats, rail access and local public transport data have not been added; verify these before planning promotion or access improvements.</div><label class="field">SEARCH COUNTRIES <input type="search" id="place-search" placeholder="Find a country…" value="${esc(state.placeQuery)}"></label></section><div class="country-grid section-gap" id="place-cards">${placeCards()}</div>`;}
function residents(){const d=byName(state.focus);return `<div class="split"><section class="panel"><p class="eyebrow">COMMUNITY EVIDENCE</p><h2>${esc(d.country)} · resident feedback</h2>${d.resident_survey_year?`<p class="sub">Destination Canada · national annual survey result · 2024</p><div class="big">${d.resident_growth_support_pct}%</div><p>Agree that their city should continue promoting itself to attract more tourists.</p><div class="support-bar" role="img" aria-label="75 percent agree, 25 percent disagree or have no opinion"><span style="width:75%"></span><span style="width:25%"></span></div><p class="sub">75% agree · remaining 25% disagree or have no opinion. This is a share of respondents, not the report’s net sentiment index.</p><p>${source(d.resident_survey_source_url,'Read the 2024 national survey summary ↗')}</p><div class="note">${esc(d.resident_survey_notes)}</div>`:empty(`No comparable national resident survey has been verified for ${d.country} in this release. No resident-satisfaction or tourism-support score is estimated.`)}<div class="toolbar"><button class="secondary" data-focus="Canada">View verified Canada survey</button></div></section><section class="panel"><h2>What national figures cannot tell us</h2><p class="sub">Use the dashboard to identify evidence needed for local decisions.</p><div class="insight"><strong>Everyday experience</strong><p>Ask residents about congestion, noise, housing and access to public places. Keep responses by destination and season.</p></div><div class="insight"><strong>Who benefits</strong><p>Pair visitor spending with local jobs, business participation and resident perceptions of the benefits.</p></div><div class="insight"><strong>A fair survey</strong><p>Record question wording, fieldwork dates, sample size, geographic coverage and weighting. Compare only compatible surveys.</p></div></section></div><section class="panel"><h3>National survey coverage</h3><div class="table-wrap"><table><thead><tr><th>Country</th><th>Status</th><th>Interpretation</th></tr></thead><tbody>${countries.map(c=>`<tr><td>${buttonCountry(c)}</td><td><span class="tag ${c.resident_survey_year?'':'gap'}">${c.resident_survey_year?'Verified · 2024':'Not verified'}</span></td><td>${c.resident_survey_year?'Support for continued promotion; not a generic satisfaction measure.':'Missing evidence in this release does not mean residents are satisfied or dissatisfied.'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function filtered(){return countries.filter(d=>d.country.toLowerCase().includes(state.query.toLowerCase())&&(state.coverage==='all'||num(d[state.coverage])!==null)).sort((a,b)=>{if(state.sort==='country')return state.dir*a.country.localeCompare(b.country);const av=num(a[state.sort]),bv=num(b[state.sort]);if(av===null)return bv===null?a.country.localeCompare(b.country):1;if(bv===null)return -1;return state.dir*(av-bv)||a.country.localeCompare(b.country);});}
const dataCols=[['country','Country'],['tourism_arrivals','Arrivals · 2024'],['travel_receipts_usd_million','Receipts · USD B'],['inbound_accommodation_nights','Inbound nights'],['accommodation_bed_places','Bed places'],['air_passengers_carried','Air passengers · 2023']];
function dataTable(){const rows=filtered();return `<div class="table-wrap"><table><caption class="sr-only">Filtered national tourism records</caption><thead><tr>${dataCols.map(([k,label])=>`<th scope="col" aria-sort="${state.sort===k?(state.dir===1?'ascending':'descending'):'none'}"><button data-sort="${k}">${label} ${state.sort===k?(state.dir===1?'↑':'↓'):'↕'}</button></th>`).join('')}</tr></thead><tbody>${rows.map(d=>`<tr><td>${buttonCountry(d)}</td>${dataCols.slice(1).map(([k])=>`<td>${displayMetric(d,k)}${k==='tourism_arrivals'?`<small>${esc(d.tourism_arrivals_type||'Not verified')}</small>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?empty('No records match these filters.'):''}<p class="sub">${rows.length} of 16 records · CSV export includes all 96 fields, original energy data, definitions and source links.</p>`;}
function dataView(){return `<section class="panel"><h2>Data you can trace</h2><p class="sub">Every row retains the original energy fields and adds tourism values, years, definitions and sources. Click a country to inspect all fields.</p><div class="toolbar"><input type="search" id="data-search" aria-label="Filter data by country" placeholder="Search country…" value="${esc(state.query)}"><select id="coverage-filter" aria-label="Filter by available measure"><option value="all">All countries</option>${[['tourism_arrivals','With arrival data'],['travel_receipts_usd_million','With receipt data'],['seasonality_year','With monthly data'],['resident_growth_support_pct','With resident survey']].map(([k,l])=>`<option value="${k}" ${state.coverage===k?'selected':''}>${l}</option>`).join('')}</select><button class="primary" id="export">Download filtered CSV ↓</button></div><div id="data-table">${dataTable()}</div></section><div class="split"><section class="panel"><h3>Source families</h3><ul class="fact-list"><li>OECD Tourism Trends and Policies 2026: 2024 arrivals, travel receipts and accommodation nights.</li><li>China National Bureau of Statistics and India Ministry of Tourism: 2024 arrival figures, with separate national definitions.</li><li>Eurostat: monthly guest nights and accommodation bed places for Croatia, France and Germany.</li><li>World Bank / ICAO: airline passengers in 2023.</li><li>Destination Canada: resident support for continued promotion, 2024.</li><li>UNESCO: illustrative heritage places. Original energy source links are retained.</li></ul></section><section class="panel"><h3>Verified numeric coverage</h3>${coverageRows()}</section></div>`;}
function showProfile(name){const d=byName(name);if(!d)return;document.getElementById('profile-content').innerHTML=`<p class="eyebrow">COUNTRY EVIDENCE BRIEF</p><h2 id="profile-title">${esc(name)}</h2><p>${esc(d.tourism_notes)}</p>${[
 ['Visitor counts',compact(d.tourism_arrivals),d.tourism_arrivals_year,d.tourism_arrivals_basis,d.tourism_arrivals_source_url],
 ['Travel receipts',money(d.travel_receipts_usd_million),d.travel_receipts_year,d.travel_receipts_basis,d.travel_receipts_source_url],
 ['Inbound accommodation nights',compact(d.inbound_accommodation_nights),d.accommodation_nights_year,d.accommodation_nights_basis,d.accommodation_nights_source_url],
 ['Accommodation bed places',compact(d.accommodation_bed_places),d.accommodation_capacity_year,d.accommodation_capacity_basis,d.accommodation_capacity_source_url],
 ['Seasonal demand',d.seasonality_year?'12 monthly observations':'Unavailable',d.seasonality_year,d.seasonality_basis,d.seasonality_source_url],
 ['Attraction example',d.attraction_example,'',d.attraction_basis,d.attraction_source_url],
 ['Airline passengers',compact(d.air_passengers_carried),d.air_passengers_year,d.air_transport_basis,d.air_transport_source_url],
 ['Resident feedback',d.resident_survey_year?d.resident_growth_support_pct+'% support continued promotion':'Unavailable',d.resident_survey_year,d.resident_survey_notes,d.resident_survey_source_url],
 ['Business electricity',num(d.business_price_usd_per_kwh)!==null?'$'+d.business_price_usd_per_kwh+'/kWh':'Unavailable',d.price_period,'Recorded business rate, not a hotel tariff. See original energy dashboard for price assumptions.',d.price_source_url]
 ].map(([title,value,year,basis,url])=>`<details><summary>${title}: ${esc(value)} ${year?'· '+esc(year):''}</summary><p>${esc(basis||'No verified observation in this release.')}</p><p>${source(url)}</p></details>`).join('')}<details><summary>All 96 CSV fields</summary><dl>${Object.entries(d).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v?(/source_url$|definitions_url$/.test(k)?source(v,'Open source ↗'):esc(v)):'Unavailable'}</dd>`).join('')}</dl></details><p><a href="energy.html">Open the original energy dashboard ↗</a></p>`;document.getElementById('profile').showModal();}
function exportCSV(){const rows=filtered(),keys=Object.keys(countries[0]);const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[keys,...rows.map(d=>keys.map(k=>d[k]))].map(r=>r.map(quote).join(',')).join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='tourism-energy-filtered.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent=`Downloaded ${rows.length} records with ${keys.length} fields.`;}
function render(){for(const id of ['focus','reference']){const el=document.getElementById(id);if(el)el.value=state[id];}const view=({overview,compare,season,place,residents,data:dataView}[state.tab]);if(view)document.getElementById('content').innerHTML=view();}
for(const id of ['focus','reference']){const el=document.getElementById(id);if(!el)continue;el.innerHTML=countries.slice().sort((a,b)=>a.country.localeCompare(b.country)).map(d=>`<option>${esc(d.country)}</option>`).join('');el.addEventListener('change',()=>{state[id]=el.value;render();});}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.tab){state.tab=target.dataset.tab;render();}if(target.dataset.profile)showProfile(target.dataset.profile);if(target.dataset.focus){state.focus=target.dataset.focus;render();}if(target.dataset.sort){if(state.sort===target.dataset.sort)state.dir*=-1;else{state.sort=target.dataset.sort;state.dir=state.sort==='country'?1:-1;}document.getElementById('data-table').innerHTML=dataTable();}if(target.id==='export')exportCSV();});
document.getElementById('content').addEventListener('change',event=>{const e=event.target;if(e.id==='metric'){state.metric=e.value;document.getElementById('chart-panel').innerHTML=chart();}if(e.id==='arrival-type'){state.arrivalType=e.value;document.getElementById('chart-panel').innerHTML=chart();}if(e.name==='compare'){if(e.checked&&state.compare.length<4)state.compare.push(e.value);else if(!e.checked)state.compare=state.compare.filter(n=>n!==e.value);document.querySelectorAll('input[name=compare]').forEach(c=>{c.checked=state.compare.includes(c.value);c.disabled=state.compare.length===4&&!c.checked;});document.getElementById('compare-count').textContent=state.compare.length+' / 4 selected';document.getElementById('comparison-table').innerHTML=compareTable();}if(e.id==='coverage-filter'){state.coverage=e.value;document.getElementById('data-table').innerHTML=dataTable();}});
document.getElementById('content').addEventListener('input',event=>{const e=event.target;if(e.id==='country-search')document.querySelectorAll('[data-country-label]').forEach(l=>l.hidden=!l.dataset.countryLabel.includes(e.value.toLowerCase()));if(e.id==='data-search'){state.query=e.value;document.getElementById('data-table').innerHTML=dataTable();}if(e.id==='place-search'){state.placeQuery=e.value;document.getElementById('place-cards').innerHTML=placeCards();}});
document.getElementById('profile-open')?.addEventListener('click',()=>showProfile(state.focus));document.getElementById('close-profile').addEventListener('click',()=>document.getElementById('profile').close());
render();
